"""Двуязычный автономный отчёт об источниковом аудите и прогнозе."""
import json
from collections import Counter


def markdown(data):
    s,e,a=data["sealed"],data["evaluation"],data["audit"]
    kinds=Counter(x["kind"] for x in s["evidence_ledger"])
    counts=s["diagnostics"]["analogy"]["counts"]
    lines=["# Свободный прогноз: аудит семантики на той же пятёрке", "",
        f'Допустимых новых кандидатов: **{len(s["predictions"]["free"])}**. Полных новых совпадений с PMC10000452: **{e["modes"]["free"]["matched_candidate_count"]}**. Независимый научный критерий не достигнут. Цель была изучена ранее; это отладочный опыт.', "",
        "## Что исправлено", "",
        f'Неизменные входы: {s["source_knowledge_count"]} блоков и {s["source_statement_count"]} компонентов утверждений. Допустимы для обучения: {s["eligible_statement_count"]} (раньше 305). Исходные карты и GOLD-файлы не изменены.', "",
        f'В отдельном аналитическом представлении явно указана безразмерность {kinds["dimensionless_statistic"]} статистик; их значения сохранены. {kinds["provenance_marker"]} ссылок на таблицы/рисунки перенесены из смысловых атрибутов в журнал происхождения. Для этого требуется явная ссылка в читаемом блоке. Неизвестные единицы коэффициентов не угадываются.', "",
        "При сопоставлении предпосылок числовые значения некоторых одноимённых измеренных статистик могут различаться при одинаковых единицах. Возраст, доза, период, группа и другие ограничения не стираются. Числовые эффекты в заключении не предсказываются. Пары не объявляются эквивалентными из-за сходной структуры.", "",
        "## Источниковый аудит", "",
        "Классификация исходных 1520 структурных пар взаимно исключающая. Это не оценка их научной совместимости:", "",
        "| Категория | Пар |", "|---|---:|"]
    for key,label in [("context_differs","Различается контекст"),("attributes_only","Различаются только атрибуты"),("identical_bundle","Одинаковая полная сигнатура"),("logic_or_status_differs","Различается логика/статус")]:
        lines.append(f'| {label} | {a["pair_categories"][key]} |')
    lines += ["", "Атрибуты включают и содержательные ограничения. Поэтому 754 пары с отличающимися атрибутами нельзя автоматически разрешить. Например, общий предикат «характеризуется» связывает несопоставимые биологические факторы, инструменты и статистические показатели.", "",
        "## Пробная генерация и контроль качества", "",
        f'Первый аналитический вариант выдал {len(data["preliminary"]["predictions"]["free"])} сырых аналогий. До загрузки цели проверены их источниковые основания: восемь переносили авторское высказывание, уже отмеченное как противоречащее собственным Results/Table 5; одна меняла формулировку диагностического определения. Они исключены из научного прогноза. Исходные утверждения сохранены. Предварительный запуск и его точный код архивированы и не оценивались по цели.', "",
        "Сходные частоты жалоб не обосновывают перенос значимости эффекта с одного показателя на другой. Авторство высказывания также не переносится по аналогии. Новая формулировка определения не считается новым эмпирическим знанием.", "",
        f'После исправления совместимы для дальнейшего поиска {counts.get("compatible_witness_pairs",0)} пар; проверены {counts.get("head_combinations",0)} тройки предпосылок. Отказов по числовому заключению: {counts.get("head_numeric_prediction_forbidden",0)}, по контексту заключения: {counts.get("head_context_differs",0)}, по определению: {counts.get("diagnostic_definition_not_a_new_forecast",0)}, по авторской атрибуции: {counts.get("source_bound_attribution_not_transferable",0)}.', "",
        f'Поддержанных шаблонов: без зависимостей {s["diagnostics"]["legacy"]["semantic"]["accepted_rules"]}; с полными группами зависимостей {s["diagnostics"]["legacy"]["graph"]["accepted_rules"]}. Разные публикации означают разное происхождение, но обзоры могут повторять одни первичные исследования.', "",
        "## Отдельная оценка", "", "| Режим | Выдано | Полные совпадения кандидатов | Полностью покрытые блоки цели |", "|---|---:|---:|---:|"]
    for mode,label in [("free","Свободный прогноз"),("known_union","Известные: первые 20 по хешу"),("frequency","Частотная база: первые 20")]:
        m=e["modes"][mode];lines.append(f'| {label} | {m["candidate_count"]} | {m["matched_candidate_count"]} | {len(m["fully_covered_target_blocks"])} |')
    lines += ["", "20 — размер выдачи базы, не число совпадений. Это не пересчёт покрытия цели полным объединением знаний. Отсутствие в цели не является опровержением. Частичное совпадение не считается полным предсказанием.", "",
        f'Фиксация: `{s["run_id"]}`. Оценка: `{e["evaluation_id"]}`. Код, словари, снимки, прогноз и квитанции чтения хешированы. Первый процесс прочитал пять источников, отдельный оценщик — одну цель. После оценки прогноз не менялся.', "",
        "## Дальнейший шаг", "",
        "Следует на маленьком источниковом наборе выделить типизированные атомарные эмпирические утверждения: показатель, исход, направление эффекта, дизайн, группа, время, единицы, способ корректировки и первичный источник. Логика целого составного блока остаётся отдельно. Потребуются также явные условия применимости операторов: общая ассоциация не даёт причинного вывода, отсутствие значимости не означает отсутствие эффекта, аналогия не переносит измеренное число или авторскую атрибуцию.", "",
        "Сначала проверить такую проекцию и операторы на скрытых заключениях внутри источников и трудных отрицательных примерах. Потом заморозить оператор, дать ему прежнюю пятёрку и только затем оценить результат. Цель не использовать для настройки словаря; независимую последующую статью оставить для окончательной проверки. Новые источники добавлять по недостающему типу доказательств, а не только ради размера корпуса.", "",
        "Модельных и сетевых вызовов: 0. Переводы готовых блоков переиспользованы. Расход токенов Codex недоступен и не выдумывался. Изменены только отдельные CLI-модули, сервисы не затронуты. Старые карты, результаты и эксперименты сохранены. Требуется экспертная научная проверка."]
    return "\n".join(lines)+"\n"


def render(data):
    encoded=json.dumps(data,ensure_ascii=False,allow_nan=False,separators=(",",":"))
    return TEMPLATE.replace("__DATA__",encoded.replace("<","\\u003c").replace("\u2028","\\u2028").replace("\u2029","\\u2029"))


TEMPLATE=r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Свободный прогноз: источниковый аудит</title>
<style>body{font:16px/1.55 system-ui;color:#17283e;background:#f4f7fb;max-width:1250px;margin:auto;padding:26px}button,select,a{font:inherit}button,select,.link{padding:9px 13px;border:1px solid #8c9cb0;border-radius:8px;background:white;color:#17283e}button,.link{cursor:pointer}button:hover,.link:hover{background:#e6edfa}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #2563eb}.toolbar{display:flex;flex-wrap:wrap;gap:9px;margin:15px 0}.card{border:1px solid #cbd5e1;border-radius:10px;background:white;padding:18px;margin:16px 0}.notice{border-left:5px solid #b45309}table{width:100%;border-collapse:collapse;background:white}td,th{text-align:left;padding:11px;border:1px solid #cbd5e1}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto}mark{background:#ffeda8}.link{text-decoration:none}h1{font-size:29px}#rows td:first-child{max-width:800px}#fragment{max-height:270px}</style>
<h1 id="heading"></h1><div class="toolbar"><button id="ru">Русский</button><button id="en">English</button><a class="link" href="report.ru.md">Отчёт / Report</a><a class="link" href="predictions.json">Прогноз JSON</a><a class="link" href="evaluation.json">Оценка JSON</a></div>
<div class="card notice" id="notice"></div><div class="card" id="summary"></div><table id="metrics"></table><div class="card" id="audit"></div><div class="card" id="next"></div>
<div class="toolbar"><label id="mode-label" for="mode"></label><select id="mode"><option value="free">Прогноз / Forecast</option><option value="known_union">Известные / Known</option><option value="frequency">Частотная база / Frequency</option><option value="rejected">Отказы / Rejections</option><option value="preliminary">Сырые аналогии, исключены / Rejected raw analogies</option><option value="ledger">Изменения проекции / Projection changes</option><option value="audit_pairs">Пары источников / Source pairs</option></select></div>
<p id="explanation"></p><table><thead><tr><th id="item-label"></th><th id="status-label"></th><th></th></tr></thead><tbody id="rows"></tbody></table>
<div class="card" id="detail" hidden><h2 id="detail-heading"></h2><div class="toolbar" id="proofs"></div><pre id="details"></pre><h3 id="fragment-heading"></h3><pre id="fragment"></pre><details><summary id="source-label"></summary><pre id="source"></pre></details></div>
<details class="card"><summary id="versions-label"></summary><pre id="versions"></pre></details>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let lang='ru';const t=(r,e)=>lang==='ru'?r:e;
const names=m=>({free:t('Свободный прогноз','Free forecast'),known_union:t('Известные: 20 по хешу','Known: 20 by hash'),frequency:t('Частотная база','Frequency baseline')}[m]);
function row(values){const r=document.createElement('tr');for(const v of values){const c=document.createElement('td');c.textContent=v;r.append(c)}return r}
function snippet(article,unit){const s=D.sources[article],u=s.units.find(x=>x.id===unit);if(!u)throw Error('Unknown unit');const c=Array.from(s.text),fragment=c.slice(u.start,u.end).join('');$('fragment').textContent=fragment;$('fragment').dataset.article=article;$('fragment').dataset.unit=unit;const mark=document.createElement('mark');mark.textContent=fragment;$('source').replaceChildren(document.createTextNode(c.slice(0,u.start).join('')),mark,document.createTextNode(c.slice(u.end).join('')))}
function text(p){const a=p.source_id||p.article_id,s=D.sources[a]?.statements[p.node_id||p.statement_id];return s?(lang==='ru'?s.text_ru:s.text):p.text||p.display_text||''}
function proofs(item){if(item.left)return [item.left,item.right];if(item.article_id)return [item];return [...(item.premises||item.source_occurrences||[])]}
function inspect(item,mode){$('detail').hidden=false;$('details').textContent=JSON.stringify(item,null,2);$('proofs').replaceChildren();$('fragment').textContent='';$('source').replaceChildren();const pp=proofs(item);if(D.evaluation.modes[mode])for(const m of D.evaluation.modes[mode].results.find(x=>x.candidate_id===item.id)?.matches||[])pp.push({article_id:D.target_article_id,statement_id:m.target_statement_id});const seen=new Set();for(const p of pp){const a=p.source_id||p.article_id,s=D.sources[a],r=s?.statements[p.node_id||p.statement_id];for(const u of r?.provenance.unit_ids||p.provenance?.unit_ids||[]){const key=a+'|'+u;if(seen.has(key))continue;seen.add(key);const b=document.createElement('button');b.textContent=s.pmcid+' · '+(r?.knowledge_id||p.knowledge_id)+' · '+u;b.onclick=()=>snippet(a,u);$('proofs').append(b)}}$('proofs').querySelector('button')?.click()}
function items(mode){return mode==='rejected'?D.sealed.diagnostics.analogy.examples:mode==='preliminary'?D.preliminary.predictions.free:mode==='ledger'?D.sealed.evidence_ledger:mode==='audit_pairs'?Object.entries(D.audit.examples).flatMap(([category,v])=>v.map(x=>({...x,category}))):D.sealed.predictions[mode]}
function render(){document.documentElement.lang=lang;$('heading').textContent=t('Свободный прогноз: источниковый аудит','Free forecast: source semantic audit');const s=D.sealed,e=D.evaluation;
$('notice').textContent=t('Допустимых новых прогнозов: ','Admissible novel forecasts: ')+s.predictions.free.length+t('. Полных новых совпадений: ','. Equivalent novel matches: ')+e.modes.free.matched_candidate_count+t('. Независимый критерий не достигнут. PMC10000452 — ранее изученный отладочный случай.','. Independent success is not established. PMC10000452 is a previously inspected debugging case.');
$('summary').textContent=t('419 блоков · 589 утверждений · допустимы: ','419 blocks · 589 statements · eligible: ')+s.eligible_statement_count+t('. Изменения только в аналитической копии: 225 безразмерных статистик и 129 ссылок на таблицы/рисунки. Числа и контекст сохранены; исходные карты неизменны.','. Only the analytical copy changes: 225 dimensionless statistics and 129 table/figure references. Values and context are preserved; original maps are unchanged.');
$('metrics').replaceChildren(row([t('Режим','Mode'),t('Выдано','Returned'),t('Полные совпадения','Equivalent candidates'),t('Покрытые блоки цели','Fully covered target blocks')]));for(const mode of ['free','known_union','frequency']){const m=e.modes[mode];$('metrics').append(row([names(mode),m.candidate_count,m.matched_candidate_count,m.fully_covered_target_blocks.length]))}
$('audit').textContent=t('Аудит 1520 исходных структурных пар: 763 различаются контекстом; 754 — только атрибутами; 2 имеют одинаковую сигнатуру; 1 различается логикой/статусом. Отличающиеся атрибуты не всегда являются лишь числовыми результатами. Исправленный поиск проверил 63 тройки: 50 требуют числового заключения, 4 имеют разный контекст, 1 меняет определение, 8 переносят авторскую атрибуцию.','Audit of 1520 original structural pairs: 763 differ in context, 754 only in attributes, 2 have identical bundles, 1 differs in logic/status. Attribute differences are not necessarily just response measurements. Corrected search checked 63 triples: 50 require numeric heads, 4 have different head context, 1 changes a definition, 8 transfer source-bound author attribution.');
$('next').textContent=t('Следующий шаг: типизированные атомарные эмпирические утверждения и операторы с явными условиями применимости. Сначала скрытые заключения внутри источников и трудные отрицательные примеры; затем заморозка и независимая оценка. Размер корпуса сам по себе не заменяет эту проверку.','Next: typed atomic empirical statements and operators with explicit applicability conditions. Start with withheld source conclusions and difficult negative controls, then freeze and independently evaluate. Corpus size alone does not replace these checks.');
for(const [id,r,en] of [['mode-label','Показать','Show'],['item-label','Содержание','Content'],['status-label','Статус','Status'],['detail-heading','Семантика и происхождение','Semantics and provenance'],['fragment-heading','Исходный фрагмент (английский)','Source fragment (English)'],['source-label','Полный источник с выделением','Full source with highlight'],['versions-label','Фиксации, версии и квитанции','Seals, versions and receipts']])$(id).textContent=t(r,en);
const mode=$('mode').value;$('explanation').textContent=mode==='preliminary'?t('9 сырых аналогий исключены после источниковой проверки ДО оценки по цели. Это не прогнозы и не подтверждённые знания.','9 raw analogies were rejected by source-only checking BEFORE target evaluation. These are not admissible forecasts or confirmed knowledge.'):mode==='known_union'||mode==='frequency'?t('20 — размер выдачи известных знаний, не число совпадений.','20 is the size of a known-knowledge baseline, not the match count.'):t('Отказы и изменения проекции можно проверить по исходным фрагментам. Вызовов моделей и сети: 0.','Rejections and projection changes can be checked against source fragments. Model and network calls: 0.');
$('rows').replaceChildren();$('detail').hidden=true;for(const x of items(mode)){const label=x.left?text(x.left)+' ↔ '+text(x.right):mode==='ledger'?text(x)+'\n'+JSON.stringify(x.original):x.source_occurrences?.map(text).join('\n')||JSON.stringify(x.atom)||x.premises?.map(text).join('\n');const status=mode==='preliminary'?t('Исключено: определение/авторская атрибуция','Rejected: definition/source attribution'):x.reason||x.category||x.kind||e.modes[mode]?.results.find(r=>r.candidate_id===x.id)?.matches.map(m=>m.relation).join('; ')||t('Полного совпадения нет','No equivalent match');const r=row([label,status]),cell=document.createElement('td'),b=document.createElement('button');b.textContent=t('Открыть','Inspect');b.onclick=()=>inspect(x,mode);cell.append(b);r.append(cell);$('rows').append(r)}if(!items(mode).length)$('rows').append(row([t('Нет допустимых новых кандидатов.','No admissible novel candidates.'),'','']));
$('versions').textContent=JSON.stringify({binding:s.binding,seal:D.seal_proof,evaluation:e.binding,receipts:D.receipts,diagnostics:s.diagnostics,preliminary_run:D.preliminary.run_id,audit_id:D.audit.audit_id},null,2)}
$('ru').onclick=()=>{lang='ru';render()};$('en').onclick=()=>{lang='en';render()};$('mode').onchange=render;render();
</script></html>'''
